10	/****************************************************************************
11	 * SPI NAND MTD driver for SF32LB58.
12	 *
13	 * Wraps the SiFli HAL SPI NAND APIs (HAL_NAND_READ_PAGE,
14	 * HAL_NAND_WRITE_PAGE, HAL_NAND_ERASE_BLK, etc.) into a NuttX
15	 * struct mtd_dev_s interface.  Pattern follows sf32lb_flash.c (NOR driver).
16	 *
17	 * The NAND flash is connected via MPI3 (QSPI3) and uses the same
18	 * FLASH_HandleTypeDef as NOR, distinguished by isNand=1.
19	 ****************************************************************************/
20	
