47	 * Pre-processor Definitions
48	 ****************************************************************************/
49	
50	/* NAND geometry defaults (overridden by HAL after init) */
51	
52	#define SF32LB_NAND_DEFAULT_PAGE_SIZE   2048
53	#define SF32LB_NAND_DEFAULT_BLK_SIZE    (128 * 1024)  /* 64 pages x 2KB */
54	
55	/* Clock divider for NAND on MPI3 */
56	
57	/****************************************************************************
58	 * Private Types
59	 ****************************************************************************/
60	
61	struct sf32lb_nand_dev_s
62	{
63	  struct mtd_dev_s mtd;
64	  FAR FLASH_HandleTypeDef *handle;
65	  uint32_t page_size;       /* bytes per page (2048 or 4096) */
66	  uint32_t block_size;      /* bytes per erase block */
67	  uint32_t total_size;      /* total flash size in bytes */
68	  uint32_t nblocks;         /* total erase blocks */
69	  FAR uint8_t *read_buf;    /* NAND page read cache (data_buf) */
70	  FAR uint8_t *write_buf;   /* NAND page write cache (data_buf_w) */
71	};
72	
73	/****************************************************************************
74	 * Private Data
75	 ****************************************************************************/
76	
77	static mutex_t g_nand_lock = NXMUTEX_INITIALIZER;
78	
79	static QSPI_FLASH_CTX_T g_spi_nand_flash_ctx;
80	static DMA_HandleTypeDef spi_nand_dma_handle;
81	static bool g_nand_hw_initialized;
82	
83	/****************************************************************************
84	 * Private Functions
85	 ****************************************************************************/
86	
87	static int nand_index = -1;   // only ONE nand support in system.
88	
89	static int sf32lb_nand_hw_init(void)
90	{
91	  HAL_StatusTypeDef status;
92	
93	  qspi_configure_t flash_cfg; // = FLASH3_CONFIG;
94	  struct dma_config flash_dma;
95	
96	  if (g_nand_hw_initialized)
97	    {
98	      return OK;
99	    }
100	
101	  memset(&g_spi_nand_flash_ctx, 0, sizeof(g_spi_nand_flash_ctx));
102	  g_spi_nand_flash_ctx.handle.Instance = FLASH4;
103	  g_spi_nand_flash_ctx.handle.base = FLASH4_BASE_ADDR;
104	  g_spi_nand_flash_ctx.handle.size =
105	    CONFIG_BSP_QSPI4_MEM_SIZE * 1024U * 1024U;
106	  g_spi_nand_flash_ctx.handle.freq = 24000000;
107	
108	  struct dma_config flash_dma4 = FLASH4_DMA_CONFIG;
109	  qspi_configure_t flash_cfg4 = FLASH4_CONFIG;
110	
111	
112	  uint16_t div = BSP_GetFlash4DIV();
113	  int clk_mode = RCC_CLK_MOD_FLASH4;
114	
115	  memcpy(&flash_cfg, &flash_cfg4, sizeof(qspi_configure_t));
116	  memcpy(&flash_dma, &flash_dma4, sizeof(struct dma_config));
117	
118	  flash_cfg.base = HCPU_MPI_SBUS_ADDR(flash_cfg.base);
119	  
120	  nand_index = 4;
121	
122	  g_spi_nand_flash_ctx.handle.freq = flash_get_freq(clk_mode, div, 1);  
123	
124	  status = HAL_FLASH_Init(&g_spi_nand_flash_ctx, &flash_cfg,
125	                          &spi_nand_dma_handle, &flash_dma, div);
126	  if (status != HAL_OK)
127	    {
128	      syslog(LOG_ERR, "ERROR: NAND HAL_FLASH_Init failed: %d\n", status);
129	      return -EIO;
130	    }
131	
132	  /* Allocate NAND page buffer required by HAL */
133	
134	  g_spi_nand_flash_ctx.handle.data_buf =
135	    kmm_zalloc(SF32LB_NAND_DEFAULT_PAGE_SIZE);
136	  if (g_spi_nand_flash_ctx.handle.data_buf == NULL)
137	    {
138	      syslog(LOG_ERR, "ERROR: NAND buffer alloc failed\n");
139	      return -ENOMEM;
140	    }
141	
142	  /* Enable ECC */
143	
144	  HAL_NAND_CONF_ECC(&g_spi_nand_flash_ctx.handle, 1);
145	
146	  g_nand_hw_initialized = true;
147	  syslog(LOG_INFO,
148	    "INFO: SPI NAND initialized on MPI3: page=%lu blk=%lu size=%luMB\n",
149	    (unsigned long)HAL_NAND_PAGE_SIZE(&g_spi_nand_flash_ctx.handle),
150	    (unsigned long)HAL_NAND_BLOCK_SIZE(&g_spi_nand_flash_ctx.handle),
151	    (unsigned long)g_spi_nand_flash_ctx.handle.size / (1024U * 1024U));
152	
153	  return OK;
154	}
155	
156	static int sf32lb_nand_lock(void)
157	{
158	  return nxmutex_lock(&g_nand_lock);
159	}
160	
161	static int sf32lb_nand_unlock(void)
162	{
163	  int ret = nxmutex_unlock(&g_nand_lock);
164	  return ret < 0 ? ret : OK;
165	}
