167	/****************************************************************************
168	 * MTD Callbacks
169	 ****************************************************************************/
170	
171	static int sf32lb_nand_geometry(FAR struct sf32lb_nand_dev_s *priv,
172	                                FAR struct mtd_geometry_s *geo)
173	{
174	  if (geo == NULL)
175	    {
176	      return -EINVAL;
177	    }
178	
179	  memset(geo, 0, sizeof(*geo));
180	  geo->blocksize = priv->block_size;
181	  geo->erasesize = priv->block_size;
182	  geo->neraseblocks = priv->nblocks;
183	  return OK;
184	}
185	
186	static ssize_t sf32lb_nand_read(FAR struct mtd_dev_s *dev, off_t offset,
187	                                size_t nbytes, FAR uint8_t *buffer)
188	{
189	  FAR struct sf32lb_nand_dev_s *priv = (FAR struct sf32lb_nand_dev_s *)dev;
190	  FAR FLASH_HandleTypeDef *handle = priv->handle;
191	  uint32_t page_size = priv->page_size;
192	  uint32_t page_addr;
193	  uint32_t page_off;
194	  uint32_t chunk;
195	  int ret;
196	
197	  if (offset < 0 || buffer == NULL || nbytes == 0)
198	    {
199	      return -EINVAL;
200	    }
201	
202	  sf32lb_nand_lock();
203	
204	  while (nbytes > 0)
205	    {
206	      page_addr = (uint32_t)offset / page_size * page_size;
207	      page_off = (uint32_t)offset % page_size;
208	      chunk = page_size - page_off;
209	      if (chunk > nbytes)
210	        {
211	          chunk = nbytes;
212	        }
213	
214	      ret = HAL_NAND_READ_PAGE(handle, page_addr, buffer, chunk);
215	      if (ret <= 0)
216	        {
217	          syslog(LOG_ERR,
218	                 "ERROR: NAND read failed: addr=0x%08lx ret=%d\n",
219	                 (unsigned long)page_addr, ret);
220	          sf32lb_nand_unlock();
221	          return -EIO;
222	        }
223	
224	      offset += chunk;
225	      buffer += chunk;
226	      nbytes -= chunk;
227	    }
228	
229	  sf32lb_nand_unlock();
230	  return (ssize_t)(nbytes == 0 ? 0 : -EIO);  /* unreachable if loop completes */
231	}
232	
233	static ssize_t sf32lb_nand_bread(FAR struct mtd_dev_s *dev,
234	                                 off_t startblock, size_t nblocks,
235	                                 FAR uint8_t *buffer)
236	{
237	  FAR struct sf32lb_nand_dev_s *priv = (FAR struct sf32lb_nand_dev_s *)dev;
238	  FAR FLASH_HandleTypeDef *handle = priv->handle;
239	  uint32_t page_size = priv->page_size;
240	  uint32_t pages_per_block = priv->block_size / page_size;
241	  uint32_t block;
242	  uint32_t page;
243	  int ret;
244	
245	  if (startblock < 0 || buffer == NULL || nblocks == 0)
246	    {
247	      return -EINVAL;
248	    }
249	
250	  sf32lb_nand_lock();
251	
252	  for (block = 0; block < nblocks; block++)
253	    {
254	      uint32_t blk_addr = (uint32_t)(startblock + block) * priv->block_size;
255	
256	      for (page = 0; page < pages_per_block; page++)
257	        {
258	          uint32_t page_addr = blk_addr + page * page_size;
259	
260	          ret = HAL_NAND_READ_PAGE(handle, page_addr, buffer, page_size);
261	          if (ret <= 0)
262	            {
263	              syslog(LOG_ERR,
264	                     "ERROR: NAND bread failed: addr=0x%08lx ret=%d\n",
265	                     (unsigned long)page_addr, ret);
266	              sf32lb_nand_unlock();
267	              return -EIO;
268	            }
269	
270	          buffer += page_size;
271	        }
272	    }
273	
274	  sf32lb_nand_unlock();
275	  return (ssize_t)nblocks;
276	}
