278	static ssize_t sf32lb_nand_bwrite(FAR struct mtd_dev_s *dev,
279	                                  off_t startblock, size_t nblocks,
280	                                  FAR const uint8_t *buffer)
281	{
282	  FAR struct sf32lb_nand_dev_s *priv = (FAR struct sf32lb_nand_dev_s *)dev;
283	  FAR FLASH_HandleTypeDef *handle = priv->handle;
284	  uint32_t page_size = priv->page_size;
285	  uint32_t pages_per_block = priv->block_size / page_size;
286	  uint32_t block;
287	  uint32_t page;
288	  int ret;
289	
290	  if (startblock < 0 || buffer == NULL || nblocks == 0)
291	    {
292	      return -EINVAL;
293	    }
294	
295	  sf32lb_nand_lock();
296	
297	  for (block = 0; block < nblocks; block++)
298	    {
299	      uint32_t blk_addr = (uint32_t)(startblock + block) * priv->block_size;
300	
301	      for (page = 0; page < pages_per_block; page++)
302	        {
303	          uint32_t page_addr = blk_addr + page * page_size;
304	
305	          ret = HAL_NAND_WRITE_PAGE(handle, page_addr, buffer, page_size);
306	          if (ret <= 0)
307	            {
308	              syslog(LOG_ERR,
309	                     "ERROR: NAND bwrite failed: addr=0x%08lx ret=%d\n",
310	                     (unsigned long)page_addr, ret);
311	              sf32lb_nand_unlock();
312	              return -EIO;
313	            }
314	
315	          buffer += page_size;
316	        }
317	    }
318	
319	  sf32lb_nand_unlock();
320	  return (ssize_t)nblocks;
321	}
