323	static int sf32lb_nand_erase(FAR struct mtd_dev_s *dev, off_t startblock,
324	                             size_t nblocks)
325	{
326	  FAR struct sf32lb_nand_dev_s *priv = (FAR struct sf32lb_nand_dev_s *)dev;
327	  FAR FLASH_HandleTypeDef *handle = priv->handle;
328	  uint32_t block;
329	  int ret;
330	
331	  if (startblock < 0 || nblocks == 0)
332	    {
333	      return -EINVAL;
334	    }
335	
336	  sf32lb_nand_lock();
337	
338	  for (block = 0; block < nblocks; block++)
339	    {
340	      uint32_t blk_addr = (uint32_t)(startblock + block) * priv->block_size;
341	
342	      ret = HAL_NAND_ERASE_BLK(handle, blk_addr);
343	      if (ret != 0)
344	        {
345	          syslog(LOG_ERR,
346	                 "ERROR: NAND erase failed: block=%lu addr=0x%08lx ret=%d\n",
347	                 (unsigned long)(startblock + block),
348	                 (unsigned long)blk_addr, ret);
349	          sf32lb_nand_unlock();
350	          return -EIO;
351	        }
352	    }
353	
354	  sf32lb_nand_unlock();
355	  return (int)nblocks;
356	}
