358	static int sf32lb_nand_ioctl(FAR struct mtd_dev_s *dev, int cmd,
359	                             unsigned long arg)
360	{
361	  FAR struct sf32lb_nand_dev_s *priv = (FAR struct sf32lb_nand_dev_s *)dev;
362	  int ret = -EINVAL;
363	
364	  switch (cmd)
365	    {
366	      case MTDIOC_GEOMETRY:
367	        {
368	          FAR struct mtd_geometry_s *geo =
369	            (FAR struct mtd_geometry_s *)((uintptr_t)arg);
370	
371	          if (geo != NULL)
372	            {
373	              ret = sf32lb_nand_geometry(priv, geo);
374	            }
375	        }
376	        break;
377	
378	      case BIOC_PARTINFO:
379	        {
380	          FAR struct partition_info_s *info =
381	            (FAR struct partition_info_s *)arg;
382	
383	          if (info != NULL)
384	            {
385	              info->numsectors = priv->nblocks;
386	              info->sectorsize = priv->block_size;
387	              info->startsector = 0;
388	              info->parent[0] = '\0';
389	              ret = OK;
390	            }
391	        }
392	        break;
393	
394	      case MTDIOC_ERASESTATE:
395	        {
396	          FAR uint8_t *result = (FAR uint8_t *)arg;
397	          *result = 0xff;
398	          ret = OK;
399	        }
400	        break;
401	
402	      case MTDIOC_BULKERASE:
403	        {
404	          ret = sf32lb_nand_erase(dev, 0, priv->nblocks) ==
405	                (int)priv->nblocks ? OK : -EIO;
406	        }
407	        break;
408	
409	      default:
410	        ret = -ENOTTY;
411	        break;
412	    }
413	
414	  return ret;
415	}
