417	static int sf32lb_nand_isbad(FAR struct mtd_dev_s *dev, off_t block)
418	{
419	  FAR struct sf32lb_nand_dev_s *priv = (FAR struct sf32lb_nand_dev_s *)dev;
420	  int ret;
421	
422	  ret = HAL_NAND_GET_BADBLK(priv->handle, (uint32_t)block);
423	  return ret;  /* 0 = good, nonzero = bad */
424	}
