439	/****************************************************************************
440	 * Name: sf32lb_nand_initialize
441	 *
442	 * Description:
443	 *   Initialize the SPI NAND flash on MPI3 and return an MTD device.
444	 *
445	 ****************************************************************************/
446	
447	FAR struct mtd_dev_s *sf32lb_nand_initialize(void)
448	{
449	  FAR struct sf32lb_nand_dev_s *priv;
450	  int ret;
451	
452	  priv = kmm_zalloc(sizeof(struct sf32lb_nand_dev_s));
453	  if (priv == NULL)
454	    {
455	      return NULL;
456	    }
457	
458	  ret = sf32lb_nand_hw_init();
459	  if (ret < 0)
460	    {
461	      kmm_free(priv);
462	      return NULL;
463	    }
464	
465	  priv->handle = &g_spi_nand_flash_ctx.handle;
466	  priv->page_size = HAL_NAND_PAGE_SIZE(priv->handle);
467	  priv->block_size = HAL_NAND_BLOCK_SIZE(priv->handle);
468	  priv->total_size = priv->handle->size;
469	  priv->nblocks = priv->total_size / priv->block_size;
470	  priv->read_buf = priv->handle->data_buf;
471	  priv->write_buf = kmm_zalloc(priv->page_size);
472	  if (priv->write_buf == NULL)
473	    {
474	      kmm_free(priv);
475	      return -ENOMEM;
476	    }
477	
478	  priv->mtd.erase   = sf32lb_nand_erase;
479	  priv->mtd.bread   = sf32lb_nand_bread;
480	  priv->mtd.bwrite  = sf32lb_nand_bwrite;
481	  priv->mtd.read    = sf32lb_nand_read;
482	  priv->mtd.ioctl   = sf32lb_nand_ioctl;
483	  priv->mtd.isbad   = sf32lb_nand_isbad;
484	  priv->mtd.markbad = sf32lb_nand_markbad;
485	  priv->mtd.name    = "nand";
486	
487	  syslog(LOG_INFO,
488	    "INFO: NAND MTD: page=%lu blk=%lu nblk=%lu total=%luMB\n",
489	    (unsigned long)priv->page_size,
490	    (unsigned long)priv->block_size,
491	    (unsigned long)priv->nblocks,
492	    (unsigned long)priv->total_size / (1024U * 1024U));
493	
494	  return (FAR struct mtd_dev_s *)priv;
495	}
