497	/****************************************************************************
498	 * Name: sf32lb_nand_register_partitions
499	 *
500	 * Description:
501	 *   Register NAND partitions as MTD character devices.
502	 *   Each partition is a sub-region of the NAND flash.
503	 *
504	 *   part_offsets[i] and part_sizes[i] are in bytes.
505	 *   A size of 0 means "use remaining flash".
506	 *
507	 ****************************************************************************/
508	
509	int sf32lb_nand_register_partitions(
510	  FAR const char *const *devnames,
511	  FAR const uint32_t *part_offsets,
512	  FAR const uint32_t *part_sizes,
513	  int npartitions)
514	{
515	  FAR struct mtd_dev_s *whole;
516	  FAR struct mtd_dev_s *part;
517	  int ret;
518	  int i;
519	
520	  whole = sf32lb_nand_initialize();
521	  if (whole == NULL)
522	    {
523	      syslog(LOG_ERR, "ERROR: Failed to initialize NAND flash\n");
524	      return -ENODEV;
525	    }
526	
527	  for (i = 0; i < npartitions; i++)
528	    {
529	      if (devnames[i] == NULL)
530	        {
531	          continue;
532	        }
533	
534	      if (part_sizes[i] == 0)
535	        {
536	          /* Single partition covering the whole device */
537	
538	          part = whole;
539	        }
540	      else
541	        {
542	          /* Create a sub-MTD for this partition */
543	
544	          part = mtd_partition(whole,
545	                              (off_t)(part_offsets[i] /
546	                                ((struct sf32lb_nand_dev_s *)whole)->
547	                                  block_size),
548	                              (size_t)(part_sizes[i] /
549	                                ((struct sf32lb_nand_dev_s *)whole)->
550	                                  block_size));
551	          if (part == NULL)
552	            {
553	              syslog(LOG_ERR,
554	                     "ERROR: mtd_partition(%s) failed\n", devnames[i]);
555	              continue;
556	            }
557	        }
558	
559	      ret = register_mtddriver(devnames[i], part, 0, part);
560	      if (ret < 0)
561	        {
562	          syslog(LOG_ERR,
563	                 "ERROR: register_mtddriver(%s) failed: %d\n",
564	                 devnames[i], ret);
565	        }
566	      else
567	        {
568	          syslog(LOG_INFO,
569	                 "INFO: NAND partition %s registered (offset=0x%08lx "
570	                 "size=0x%08lx)\n",
571	                 devnames[i],
572	                 (unsigned long)part_offsets[i],
573	                 (unsigned long)part_sizes[i]);
574	        }
575	    }
576	
577	  return OK;
578	}
