122	int rt_nand_read(uint32_t addr, uint8_t *buf, int size)
123	{
124	    int offset, cnt, remain, fill, res;
125	    uint32_t taddr = addr;
126	    uint8_t *tbuf = buf;
127	    if (nand_index < 0)
128	        return 0;
129	
130	    FLASH_HandleTypeDef *hflash = &(spi_nand_handle.handle);
131	    if ((addr < hflash->base) || (addr + size > (hflash->base + hflash->size)))
132	        return 0;
133	
134	    offset = 0;
135	    fill = 0;
136	    cnt = 0;
137	    remain = size;
138	    if (taddr & (nand_pagesize - 1)) // not page aligned
139	    {
140	        rt_mutex_take(&nand_mutex, RT_WAITING_FOREVER);
141	        uint8_t *cach_buf = hflash->data_buf;
142	        offset = taddr & (nand_pagesize - 1); //
143	        fill = nand_pagesize - offset;
144	        fill = fill < remain ? fill : remain;
145	        taddr &= ~(nand_pagesize - 1);
146	        if (taddr != (uint32_t) hflash->data_addr)
147	        {
148	            res = rt_nand_read_page(taddr, cach_buf, nand_pagesize, NULL, 0);
149	            if (res != nand_pagesize)
150	            {
151	                hflash->data_addr = NULL;
152	                rt_mutex_release(&nand_mutex);
153	                return 0;
154	            }
155	            hflash->data_addr = (uint8_t *) taddr;
156	        }
157	        memcpy(tbuf, cach_buf + offset, fill);
158	        rt_mutex_release(&nand_mutex);
159	        remain -= fill;
160	        taddr += nand_pagesize;
161	        tbuf += fill;
162	        cnt += fill;
163	    }
164	    while (remain >= nand_pagesize)
165	    {
166	        res = rt_nand_read_page(taddr, tbuf, nand_pagesize, NULL, 0);
167	        if (res != nand_pagesize)
168	            return 0;
169	        remain -= nand_pagesize;
170	        taddr += nand_pagesize;
171	        tbuf += nand_pagesize;
172	        cnt += nand_pagesize;
173	    }
174	    if (remain > 0)
175	    {
176	        res = rt_nand_read_page(taddr, tbuf, remain, NULL, 0);
177	        if (res != remain)
178	            return 0;
179	        cnt += remain;
180	    }
181	    return cnt;
182	}
