184	int rt_nand_write(uint32_t addr, const uint8_t *buf, int size)
185	{
186	    int offset, cnt, remain;
187	    uint32_t taddr = addr;
188	    uint8_t *tbuf = (uint8_t *)buf;
189	    if (nand_index < 0)
190	        return 0;
191	
192	    FLASH_HandleTypeDef *hflash = &(spi_nand_handle.handle);
193	    if ((addr < hflash->base) || (addr + size > (hflash->base + hflash->size)))
194	        return 0;
195	
196	    offset = 0;
197	    cnt = 0;
198	    remain = size;
199	    if (taddr & (nand_pagesize - 1)) // not page aligned
200	    {
201	        RT_ASSERT(0); // NOT SUUPPORT unaligned write
202	        offset = nand_pagesize - (taddr & (nand_pagesize - 1));
203	        cnt = rt_nand_write_page(taddr, tbuf, offset, NULL, 0);
204	        remain -= offset;
205	        taddr += offset;
206	        tbuf += offset;
207	    }
208	    while (remain >= nand_pagesize)
209	    {
210	        cnt += rt_nand_write_page(taddr, tbuf, nand_pagesize, NULL, 0);
211	        remain -= nand_pagesize;
212	        taddr += nand_pagesize;
213	        tbuf += nand_pagesize;
214	    }
215	    if (remain > 0)
216	    {
217	        RT_ASSERT(0); // NOT SUUPPORT unaligned write
218	        cnt += rt_nand_write_page(taddr, tbuf, nand_pagesize, NULL, 0);
219	    }
220	    return cnt;
221	
