252	int rt_nand_read_page(uint32_t addr, uint8_t *data, int size, uint8_t *spare, int spare_len)
253	{
254	    int res;
255	    if (nand_index < 0)
256	        return 0;
257	
258	    FLASH_HandleTypeDef *hflash = &(spi_nand_handle.handle);
259	
260	    if (hflash == NULL || size > nand_pagesize || hflash->buf_mode == 0)  // only support read 1 page
261	    {
262	        RT_ASSERT(0);
263	        return 0;
264	    }
265	    if (addr >= hflash->base)
266	        addr -= hflash->base;
267	#ifdef BSP_USING_SWITCH_MPI2_SDIO
268	    rt_switch_mpi2_lock();
269	#endif
270	#ifdef BSP_USING_BBM
271	    int blk, page, offset;
272	
273	    blk = addr / nand_blksize;
274	    page = (addr / nand_pagesize) & (nand_blksize / nand_pagesize - 1);
275	    offset = addr & (nand_pagesize - 1);
276	
277	    if (blk >= 8192) // max support 8Gb ? for address error issue
278	        RT_ASSERT(0);
279	
280	    rt_nand_lock();
281	    res = bbm_read_page(blk, page, offset, data, size, spare, spare_len);
282	    rt_nand_unlock();
283	#else
284	
285	    //rt_thread_delay(1);
286	    rt_nand_lock();
287	    SCB_InvalidateDCache_by_Addr((void *)hflash->base, nand_pagesize + SPI_NAND_MAXOOB_SIZE);
288	    if (((addr & nand_blksize) != 0) && (hflash->wakeup != 0))
289	        SCB_InvalidateDCache_by_Addr((void *)(hflash->base + (1 << 12)), nand_pagesize + SPI_NAND_MAXOOB_SIZE);// TODO: only 2048 page size has plane select issue
290	#if (NAND_BUF_CPY_MODE == 1)
291	    SCB_InvalidateDCache_by_Addr(data, size);
292	#endif
293	    local_edma_lock();
294	    res = HAL_NAND_READ_WITHOOB(hflash, addr, data, size, spare, spare_len);
295	    local_edma_unlock();
296	
297	    rt_nand_unlock();
298	    if (res <= 0)
299	        LOG_E("NAND Read2 error code %d\n", hflash->ErrorCode);
300	#endif
301	
302	#if 0   // debug use, for some case controller sames not work
303	    int i;
304	    uint8_t *tbuf = data;
305	    for (i = 0; i < 128; i++)
306	    {
307	        if (*tbuf != 0xcc)
308	            break;
309	        tbuf++;
310	    }
311	    if (i == 128)   // read all cc ? status error?
312	        RT_ASSERT(0);
313	#endif
314	#ifdef BSP_USING_SWITCH_MPI2_SDIO
315	    rt_switch_mpi2_unlock();
316	#endif
317	    return res;
318	}
