412	int rt_nand_write_page(uint32_t addr, const uint8_t *buf, int size, const uint8_t *spare, int spare_len)
413	{
414	    int res = 0;
415	    if (nand_index < 0)
416	        return 0;
417	
418	    FLASH_HandleTypeDef *hflash = &(spi_nand_handle.handle);
419	    if (addr >= hflash->base)
420	        addr -= hflash->base;
421	    // write must be page aligned
422	    if ((addr & (nand_pagesize - 1)) != 0 || size > nand_pagesize)
423	    {
424	        LOG_E("Write nand %x must be page aligned\n", addr);
425	        return 0;
426	    }
427	    if ((size == nand_pagesize) && (spare_len == 0)) // full user page write, check if al FF
428	    {
429	        int i;
430	        if (((uint32_t)buf & 3) == 0)
431	        {
432	            uint32_t *chk = (uint32_t *)buf;
433	            for (i = 0; i < nand_pagesize / 4; i++)
434	            {
435	                if (chk[i] != 0xffffffff)
436	                    break;
437	            }
438	            if (i == nand_pagesize / 4) // full page data is 0xff, do not need write to flash
439	            {
440	                LOG_D("Full page 0xff, do not need write to flash at pos 0x%x\n", addr);
441	                return size;
442	            }
443	        }
444	        else
445	        {
446	            uint8_t *chk8 = (uint8_t *)buf;
447	            for (i = 0; i < nand_pagesize; i++)
448	            {
449	                if (chk8[i] != 0xff)
450	                    break;
451	            }
452	            if (i == nand_pagesize) // full page data is 0xff, do not need write to flash
453	            {
454	                LOG_D("Full page 0xff, do not need write to flash at pos 0x%x\n", addr);
455	                return size;
456	            }
457	        }
458	    }
459	#ifdef BSP_USING_SWITCH_MPI2_SDIO
460	    rt_switch_mpi2_lock();
461	#endif
462	#ifdef BSP_NAND_CHECK_BEFORE_WRITE
463	    SCB_InvalidateDCache_by_Addr((void *)hflash->base, nand_pagesize + SPI_NAND_MAXOOB_SIZE);
464	    SCB_InvalidateDCache_by_Addr((void *)hflash->data_buf_w, nand_pagesize + SPI_NAND_MAXOOB_SIZE);
465	
466	    rt_nand_lock();
467	
468	#ifdef BSP_USING_BBM
469	    int blk2, page2;
470	    blk2 = addr / nand_blksize;
471	    page2 = (addr / nand_pagesize) & (nand_blksize / nand_pagesize - 1);
472	
473	    res = bbm_read_page(blk2, page2, 0, hflash->data_buf_w, nand_pagesize, NULL, 0);
474	#else
475	    res = HAL_NAND_READ_WITHOOB(hflash, addr, hflash->data_buf_w, nand_pagesize, NULL, 0);
476	#endif  //BSP_USING_BBM
477	
478	    if (res != nand_pagesize)
479	    {
480	        rt_nand_unlock();
481	        LOG_E("Read fail when check before write, err 0x%x with addr 0x%x\n", hflash->ErrorCode, addr);
482	        RT_ASSERT(0);
483	    }
484	    else
485	    {
486	        int i = 0;
487	        uint32_t *chk = (uint32_t *)hflash->data_buf_w;
488	        for (i = 0; i < nand_pagesize / 4; i++)
489	        {
490	            if (chk[i] != 0xffffffff)
491	            {
492	                rt_nand_unlock();
493	                LOG_E("NAND not clean before write, 0x%08x is not FF at POS %d with addr 0x%x\n", chk[i], i, addr);
494	                RT_ASSERT(0);
495	            }
496	        }
497	    }
498	    rt_nand_unlock();
499	#endif  //BSP_NAND_CHECK_BEFORE_WRITE
500	#ifdef BSP_USING_BBM
501	    int blk, page;
502	
503	    blk = addr / nand_blksize;
504	    page = (addr / nand_pagesize) & (nand_blksize / nand_pagesize - 1);
505	    rt_nand_lock();
506	    res = bbm_write_page(blk, page, (uint8_t *)buf, (uint8_t *)spare, spare_len);
507	    rt_nand_unlock();
508	#else
509	    if (hflash == NULL || size > nand_pagesize)  // only support read 1 page
510	    {
511	#ifdef BSP_USING_SWITCH_MPI2_SDIO
512	        rt_switch_mpi2_unlock();
513	#endif
514	        return 0;
515	    }
516	
517	    rt_nand_lock();
518	    res = HAL_NAND_WRITE_WITHOOB(hflash, addr, buf, size, spare, spare_len);
519	    rt_nand_unlock();
520	    if (res <= 0)
521	        LOG_E("NAND Write2 fail, error code 0x%x\n", hflash->ErrorCode);
522	#endif
523	#ifdef BSP_USING_SWITCH_MPI2_SDIO
524	    rt_switch_mpi2_unlock();
525	#endif
526	    return res;
527	}
