530	{
531	    int res;
532	    if (nand_index < 0)
533	    {
534	        LOG_E("NAND erase id failed: 0x%x\n", addr);
535	        return -1;
536	    }
537	
538	    FLASH_HandleTypeDef *hflash = &(spi_nand_handle.handle);
539	    if (hflash == NULL)
540	        return -1;
541	
542	    if (addr >= hflash->base)
543	        addr -= hflash->base;
544	#ifdef BSP_USING_SWITCH_MPI2_SDIO
545	    rt_switch_mpi2_lock();
546	#endif
547	#ifdef BSP_USING_BBM
548	    int blk;
549	
550	    blk = addr / nand_blksize;
551	    rt_nand_lock();
552	    res = bbm_erase_block(blk);
553	    rt_nand_unlock();
554	#else
555	    if (!IS_ALIGNED(nand_blksize, addr))  // address should be block aligned
556	    {
557	#ifdef BSP_USING_SWITCH_MPI2_SDIO
558	        rt_switch_mpi2_unlock();
559	#endif
560	        return -2;
561	    }
562	
563	#ifndef BSP_FORCE_ERASE_NAND
