566	        SCB_InvalidateDCache_by_Addr((void *)(hflash->base + (1 << 12)), nand_pagesize + SPI_NAND_MAXOOB_SIZE); // TODO: only 2048 page size has plane select issue
567	
568	    int bad = HAL_NAND_GET_BADBLK(hflash, addr / nand_blksize);
569	    if (bad)   // block is bad, do not erase, or bad mark will be cover
570	    {
571	        LOG_E("Blk with address 0x%x is bad, do not erase2\n", addr);
572	#ifdef BSP_USING_SWITCH_MPI2_SDIO
573	        rt_switch_mpi2_unlock();
574	#endif
575	        return -3;
576	    }
577	#endif
578	
579	    rt_nand_lock();
580	    res = HAL_NAND_ERASE_BLK(hflash, addr);
581	    rt_nand_unlock();
582	
583	    if (res != 0)
584	        LOG_E("Erase error code 0x%x at pos 0x%x\n", hflash->ErrorCode, addr);
585	#endif
586	#ifdef BSP_USING_SWITCH_MPI2_SDIO
587	    rt_switch_mpi2_unlock();
588	#endif
589	    return res;
590	}
