687	
688	#if defined(BSP_ENABLE_QSPI3) && (BSP_QSPI3_MODE == SPI_MODE_NAND)
689	    qspi_configure_t flash_cfg3 = FLASH3_CONFIG;
690	    struct dma_config flash_dma3 = FLASH3_DMA_CONFIG;
691	
692	    // set clock divider, it related with source clock freq
693	    div = BSP_GetFlash3DIV();
694	    clk_mode = RCC_CLK_MOD_FLASH3;
695	    memcpy(&flash_cfg, &flash_cfg3, sizeof(qspi_configure_t));
696	    memcpy(&flash_dma, &flash_dma3, sizeof(struct dma_config));
697	    nand_index = 3;
698	#elif defined(BSP_ENABLE_QSPI4) && (BSP_QSPI4_MODE == SPI_MODE_NAND)
699	    qspi_configure_t flash_cfg4 = FLASH4_CONFIG;
700	    struct dma_config flash_dma4 = FLASH4_DMA_CONFIG;
701	
702	    // set clock divider, it related with source clock freq
