704	    clk_mode = RCC_CLK_MOD_FLASH4;
705	    memcpy(&flash_cfg, &flash_cfg4, sizeof(qspi_configure_t));
706	    memcpy(&flash_dma, &flash_dma4, sizeof(struct dma_config));
707	    nand_index = 4;
708	#elif defined(BSP_ENABLE_QSPI2) && (BSP_QSPI2_MODE == SPI_MODE_NAND)
709	    qspi_configure_t flash_cfg2 = FLASH2_CONFIG;
710	    struct dma_config flash_dma2 = FLASH2_DMA_CONFIG;
711	
712	    // set clock divider, it related with source clock freq
713	    div = BSP_GetFlash2DIV();
714	    clk_mode = RCC_CLK_MOD_FLASH2;
715	    memcpy(&flash_cfg, &flash_cfg2, sizeof(qspi_configure_t));
716	    memcpy(&flash_dma, &flash_dma2, sizeof(struct dma_config));
717	    nand_index = 2;
718	#endif
719	
720	    // for nand, use nand interface to read/write, do not use AHB, so do not care address
721	    if (flash_cfg.SpiMode == SPI_MODE_NAND)
722	    {
723	#ifdef SOC_SF32LB55X
724	        if (flash_cfg.msize > (QSPI3_MAX_SIZE >> 20))
725	            flash_cfg.msize = QSPI3_MAX_SIZE >> 20;
726	#else
727	        flash_cfg.base = HCPU_MPI_SBUS_ADDR(flash_cfg.base);
728	#endif
729	    }
730	    else
731	    {
732	        nand_index = -1;
733	        return 0;
734	    }
735	
736	    spi_nand_handle.handle.freq = flash_get_freq(clk_mode, div, 1);
737	    // init hardware, set dma, clock
738	    res = HAL_FLASH_Init(&spi_nand_handle, &flash_cfg, &spi_nand_dma_handle, &flash_dma, div);
739	    if (res == HAL_OK)
740	    {
741	     rt_kprintf("NAND ID 0x%x\n", spi_nand_handle.dev_id);
742	     if(spi_nand_handle.dev_id == 0xb034b0)
743	     {
744	        nand_pagesize = 4096;
745	        nand_blksize = 0x80000;   
746	     }
747	     else
748	     {
749	        nand_pagesize = HAL_NAND_PAGE_SIZE(&spi_nand_handle.handle);
750	        nand_blksize = HAL_NAND_BLOCK_SIZE(&spi_nand_handle.handle); 
751	     }
752	
753	#ifndef CFG_BOOTLOADER
754	        if (gnand_cache_buf == NULL)
755	            gnand_cache_buf = (uint8_t *)rt_malloc(nand_pagesize + SPI_NAND_MAXOOB_SIZE);
756	        if (gnand_cache_buf == NULL)
757	            goto abnormal;
758	        if (gnand_cache_buf_w == NULL)
759	            gnand_cache_buf_w = (uint8_t *)rt_malloc(nand_pagesize + SPI_NAND_MAXOOB_SIZE);
760	        if (gnand_cache_buf_w == NULL)
761	            goto abnormal;
762	#endif
763	        spi_nand_handle.handle.data_buf = (uint8_t *)gnand_cache_buf;
764	        spi_nand_handle.handle.data_buf_w = (uint8_t *)gnand_cache_buf_w;
765	
766	        spi_nand_handle.handle.buf_mode = 1;    // default set to buffer mode for nand
767	        HAL_NAND_CONF_ECC(&spi_nand_handle.handle, 1); // default enable ECC if support !
768	#ifdef BSP_USING_BBM
769	
770	#ifndef CFG_BOOTLOADER
771	        if (gbbm_cache_buf == NULL)
772	            gbbm_cache_buf = (uint8_t *)rt_malloc(nand_pagesize + SPI_NAND_MAXOOB_SIZE);
773	        if (gbbm_cache_buf == NULL)
774	            goto abnormal;
775	#endif
776	        bbm_register_log((bbm_log_func)rt_kprintf);
777	        bbm_set_page_size(nand_pagesize);
778	        bbm_set_blk_size(nand_blksize);
779	#ifdef APP_BSP_TEST
780	        void nand_clear_pattern(void);
781	        nand_clear_pattern();
782	#endif
783	        sif_bbm_init(spi_nand_handle.total_size, (uint8_t *)gbbm_cache_buf);
784	#endif
785	
786	        return 1;
787	    }
788	
789	    nand_index = -1;
790	    return 0;
791	#ifndef CFG_BOOTLOADER
792	abnormal:
793	    rt_kprintf("Malloc nand cache buffer fail\n");
794	    if (gnand_cache_buf) rt_free(gnand_cache_buf);
795	    if (gnand_cache_buf_w) rt_free(gnand_cache_buf_w);
