1028	
1029	    // move these configure to menuconfig or configure file?
1030	    mtd->page_size = nand_pagesize;
1031	    mtd->oob_size = 64;
1032	    mtd->oob_free = 24;
1033	    mtd->plane_num = 2;
1034	    mtd->pages_per_block = pages_per_block;
1035	    mtd->block_total = size / blk_size;
1036	    mtd->block_start = offset / blk_size;
1037	    mtd->block_end = mtd->block_start + mtd->block_total - 1;
1038	    mtd->cache_buf = NULL;
1039	    mtd->blk_cnum = 0;
1040	    mtd->ops = &spi_nand_ops;
1041	    mtd->parent.user_data = (void *)flash_base;
1042	    rt_mtd_nand_register_device(name, mtd);
