1133	// 0 if success, -2 for ecc can not recover , 1 for ecc recover error, -1 for others
1134	int port_read_page(int blk, int page, int offset, uint8_t *buff, uint32_t size, uint8_t *spare, uint32_t spare_len)
1135	{
1136	    int res;
1137	    uint32_t addr = (blk * nand_blksize) + (page * nand_pagesize) + offset;
1138	    if (nand_index < 0)
1139	    {
1140	        LOG_E("No valid nand controller init\n");
1141	        RT_ASSERT(0);
1142	        return 0;
1143	    }
1144	
1145	    FLASH_HandleTypeDef *hflash = &(spi_nand_handle.handle);
1146	    if ((offset + size) > nand_pagesize)
1147	    {
1148	        LOG_E("Not support cross page read, offset %d, size %d\n", offset, size);
1149	        RT_ASSERT(0);
1150	    }
1151	
1152	#ifdef APP_BSP_TEST
1153	    enum NAND_PATT_MODE_T testp = nand_get_pattern(hflash->base + addr);
1154	    if (testp != NAND_NO_ERR)
1155	    {
1156	        if (NAND_READ_ECC_FAIL == testp)
1157	        {
1158	            hflash->ErrorCode = 0x8002;
1159	            LOG_E("Read has ecc fail pat at 0x%x\n", hflash->base + addr);
1160	            nand_clear_pattern();
1161	            return 0;
1162	        }
1163	        if (NAND_FILL_DATA == testp)
1164	        {
1165	            hflash->ErrorCode = 0;
1166	            memcpy(buff, spi_nand_handle.handle.data_buf, size);
1167	            nand_clear_pattern();
1168	            return size + spare_len;
1169	        }
1170	    }
1171	#endif //APP_BSP_TEST
1172	
1173	    SCB_InvalidateDCache_by_Addr((void *)hflash->base, nand_pagesize + SPI_NAND_MAXOOB_SIZE);
1174	    if (((addr & nand_blksize) != 0) && (hflash->wakeup != 0))
1175	        SCB_InvalidateDCache_by_Addr((void *)(hflash->base + (1 << 12)), nand_pagesize + SPI_NAND_MAXOOB_SIZE); // TODO: only 2048 page size has plane select issue
1176	#if (NAND_BUF_CPY_MODE == 1)
1177	    SCB_InvalidateDCache_by_Addr(buff, size);   // for cached buffer, need invalidate manual when using dma
1178	#endif
1179	    local_edma_lock();
1180	    res = HAL_NAND_READ_WITHOOB(hflash, addr, buff, size, spare, spare_len);
1181	    local_edma_unlock();
1182	
1183	    if (res <= 0)
1184	    {
1185	        LOG_E("NAND Read error code 0x%x, blk %d, page %d, offset %d, size %d\n",
1186	              hflash->ErrorCode, blk, page, offset, size);
1187	        LOG_E("Buffer %p\n", buff);
1188	    }
1189	
1190	#ifdef APP_BSP_TEST
1191	    if (testp != NAND_NO_ERR)
1192	    {
1193	        nand_clear_pattern();
1194	        if ((NAND_READ_ECC_WORK == testp) && (res > 0))
1195	        {
1196	            hflash->ErrorCode = 0x8000;
1197	            LOG_E("Read has ecc pat at 0x%x\n", hflash->base + addr);
1198	        }
1199	    }
1200	#endif
1201	
1202	    return res;
1203	}
