1205	// 0 if success, -3 for p fail , -1 for others error
1206	int port_write_page(int blk, int page, uint8_t *data, uint8_t *spare, uint32_t spare_len)
1207	{
1208	    int res;
1209	    uint32_t addr = (blk * nand_blksize) + (page * nand_pagesize);
1210	    if (nand_index < 0)
1211	        return 0;
1212	    FLASH_HandleTypeDef *hflash = &(spi_nand_handle.handle);
1213	
